function validate([n]) {
  if (!Number.isInteger(n)) return 'n must be a whole number.';
  if (n < 100 || n > 999) return 'n must have exactly three digits (100 to 999).';
  return null;
}

reference:
function isFascinating(n) {
  const joined = String(n) + String(2 * n) + String(3 * n);
  const count = new Array(10).fill(0);

  for (const ch of joined) {
    count[Number(ch)]++;
  }
  if (count[0] !== 0) {
    return false;
  }
  for (let digit = 1; digit <= 9; digit++) {
    if (count[digit] !== 1) {
      return false;
    }
  }
  return true;
}

brute:
function isFascinating(n) {
  const digits = [n, 2 * n, 3 * n].join('').split('').sort().join('');
  return digits === '123456789';
}

