function generate(rand, size) {
  // Fascinating values are rare, so mix them in on purpose.
  const special = [192, 219, 273, 327];
  if (rand() < 0.3) return [special[Math.floor(rand() * special.length)]];
  if (size === 'small' && rand() < 0.2) return [[100, 999, 333, 334, 123, 111][Math.floor(rand() * 6)]];
  return [100 + Math.floor(rand() * 900)];
}
